def run_cmd(cmd, cwd=None, quiet=False):
    if quiet:
        print(f"Executing (Quietly): {' '.join(cmd)}")
        subprocess.run(cmd, cwd=cwd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    else:
        print(f"Executing: {' '.join(cmd)}")
        subprocess.run(cmd, cwd=cwd, check=True)


def _nuclear_delete_flash_attn():
    print("🧹 Physically locating and deleting any residual flash_attn files in sys.path...")
    import sys, shutil
    search_paths = list(sys.path)
    import site
    try:
        search_paths.extend(site.getsitepackages())
    except:
        pass
    try:
        search_paths.append(site.getusersitepackages())
    except:
        pass
        
    for path in set(search_paths):
        if not path or not os.path.isdir(path):
            continue
        try:
            for name in os.listdir(path):
                if "flash_attn" in name.lower() or "flash-attn" in name.lower():
                    target = os.path.join(path, name)
                    print(f"   Removing residual flash_attn target: {target}")
                    if os.path.isdir(target):
                        shutil.rmtree(target, ignore_errors=True)
                    else:
                        os.remove(target)
        except Exception as e:
            print(f"   ⚠️ Error scanning/deleting in {path}: {e}")


def setup_sitecustomize():
    print("🛠️ Setting up sitecustomize patch for PyTorch schema validation...")
    import site
    paths = []
    try:
        paths.extend(site.getsitepackages())
    except Exception:
        pass
    try:
        paths.append(site.getusersitepackages())
    except Exception:
        pass
    
    paths = list(set([p for p in paths if p and os.path.isdir(p)]))
    print(f"   Candidate site-packages paths: {paths}")
    
    patch_content = """# 🛡️ GLOBAL PYTORCH INFER_SCHEMA PATCH FOR Python 3.10+ Union Types Compatibility
import sys
import types
import importlib.util
import typing
import builtins

# 🛡️ Poison pill for flash_attn to block imports globally at Python startup
_flash_attn_stub = types.ModuleType('flash_attn')
_flash_attn_stub.__spec__ = importlib.util.spec_from_loader('flash_attn', loader=None)
_flash_attn_stub.__version__ = '0.0.0'
_flash_attn_stub.flash_attn_varlen_func = None
_flash_attn_stub.flash_attn_func = None
sys.modules['flash_attn'] = _flash_attn_stub
sys.modules['flash_attn.flash_attn_interface'] = _flash_attn_stub

try:
    orig_import = builtins.__import__
    _in_patch = False
    
    def _apply_infer_schema_patch():
        try:
            if "torch" in sys.modules:
                for mod in ["torch.library", "torch._library", "torch._library.infer_schema", "torch._library.custom_ops", "torch._custom_op", "torch._custom_op.impl"]:
                    try:
                        import importlib
                        importlib.import_module(mod)
                    except Exception:
                        pass

                def clean_func_annotations(func):
                    if not hasattr(func, "__annotations__") or not func.__annotations__:
                        return func
                    try:
                        import torch
                        new_annotations = {}
                        for name, annotation in func.__annotations__.items():
                            if isinstance(annotation, str):
                                anno_str = annotation.replace(" ", "")
                                if anno_str == "float|None":
                                    annotation = typing.Optional[float]
                                elif anno_str == "bool|None":
                                    annotation = typing.Optional[bool]
                                elif anno_str == "int|None":
                                    annotation = typing.Optional[int]
                                elif anno_str == "torch.Tensor":
                                    annotation = torch.Tensor
                                elif anno_str == "torch.Tensor|None":
                                    annotation = typing.Optional[torch.Tensor]
                                elif anno_str == "tuple[torch.Tensor,torch.Tensor]":
                                    annotation = typing.Tuple[torch.Tensor, torch.Tensor]
                                else:
                                    try:
                                        ns = {"torch": torch, "typing": typing, "Optional": typing.Optional, "List": typing.List, "Tuple": typing.Tuple}
                                        if "|" in annotation:
                                            parts = [p.strip() for p in annotation.split("|")]
                                            if "None" in parts:
                                                non_none = [p for p in parts if p != "None"]
                                                if len(non_none) == 1:
                                                    annotation = f"Optional[{non_none[0]}]"
                                        annotation = eval(annotation, ns)
                                    except Exception:
                                        pass

                            try:
                                origin = typing.get_origin(annotation)
                                args = typing.get_args(annotation)
                                if origin in (typing.Union, getattr(typing, "UnionType", None)) or (hasattr(origin, "__name__") and origin.__name__ == "UnionType"):
                                    if type(None) in args:
                                        non_none = [a for a in args if a is not type(None)]
                                        if len(non_none) == 1:
                                            annotation = typing.Optional[non_none[0]]
                                elif origin is tuple:
                                    annotation = typing.Tuple[args]
                                elif origin is list:
                                    annotation = typing.List[args[0]]
                            except Exception:
                                pass

                            new_annotations[name] = annotation
                        func.__annotations__ = new_annotations
                    except Exception:
                        pass
                    return func

                def make_wrapper(orig_fn):
                    def wrapper(prototype_function, *args, **kwargs):
                        try:
                            clean_func_annotations(prototype_function)
                        except Exception:
                            pass
                        return orig_fn(prototype_function, *args, **kwargs)
                    return wrapper

                for m_name, module in list(sys.modules.items()):
                    if m_name.startswith("torch") and module:
                        for attr_name in dir(module):
                            if attr_name == "infer_schema":
                                try:
                                    orig = getattr(module, attr_name)
                                    if callable(orig) and not hasattr(orig, "_is_patched"):
                                        wrapped = make_wrapper(orig)
                                        wrapped._is_patched = True
                                        setattr(module, attr_name, wrapped)
                                except Exception:
                                    pass
        except Exception:
            pass

    def patched_import(name, globals=None, locals=None, fromlist=(), level=0):
        global _in_patch
        module = orig_import(name, globals, locals, fromlist, level)
        if name.startswith("torch") and not _in_patch:
            _in_patch = True
            try:
                _apply_infer_schema_patch()
            except Exception:
                pass
            finally:
                _in_patch = False
        return module

    builtins.__import__ = patched_import
    _apply_infer_schema_patch()

except Exception:
    pass
"""
    for p in paths:
        try:
            sitecustomize_path = os.path.join(p, "sitecustomize.py")
            if os.path.exists(sitecustomize_path):
                with open(sitecustomize_path, "r", encoding="utf-8") as f:
                    content = f.read()
                if "GLOBAL PYTORCH INFER_SCHEMA PATCH" not in content:
                    new_content = patch_content + "\n" + content
                    with open(sitecustomize_path, "w", encoding="utf-8") as f:
                        f.write(new_content)
                    print(f"   ✅ Prepended to existing sitecustomize at: {sitecustomize_path}")
                else:
                    print(f"   ✅ sitecustomize at {sitecustomize_path} already patched")
            else:
                with open(sitecustomize_path, "w", encoding="utf-8") as f:
                    f.write(patch_content)
                print(f"   ✅ Created new sitecustomize at: {sitecustomize_path}")
        except Exception as e:
            print(f"   ⚠️ Failed writing to {p}: {e}")




def _apply_physical_patches():
    """
    Applies regex-based physical patches to mmengine files on disk.
    This ensures compatibility across subprocesses on Python 3.12.
    """
    print("🛠️ Applying robust physical patches to mmengine...")
    import site
    sp = site.getsitepackages()[0]
    
    patches = [
        {
            "path": os.path.join(sp, "mmengine", "optim", "optimizer", "builder.py"),
            "old": re.compile(r"^(\s*)OPTIMIZERS\.register_module\(name='Adafactor', module=Adafactor\)", re.MULTILINE),
            "new": r"\1OPTIMIZERS.register_module(name='Adafactor', module=Adafactor, force=True)",
            "name": "Adafactor force=True"
        },
        {
            "path": os.path.join(sp, "mmengine", "registry", "registry.py"),
            "old": re.compile(r"^(\s*)module = inspect\.getmodule\(sys\._getframe\(2\)\)", re.MULTILINE),
            "new": r"\1try:\n\1    module = inspect.getmodule(sys._getframe(2))\n\1except TypeError:\n\1    module = None",
            "name": "Registry infer_scope TypeError"
        },
        {
            "path": os.path.join(sp, "mmengine", "utils", "dl_utils", "misc.py"),
            "old": re.compile(r"^(\s*)ext_loader = pkgutil\.find_loader\('mmcv\._ext'\)", re.MULTILINE),
            "new": r"\1try:\n\1    ext_loader = pkgutil.find_loader('mmcv._ext')\n\1except (ImportError, ValueError):\n\1    ext_loader = None",
            "name": "mmcv_full_available ValueError"
        },
        {
            "path": os.path.join(sp, "mmengine", "runner", "checkpoint.py"),
            "old": re.compile(r"^(\s*)checkpoint = torch\.load\(([^,)]+,\s*[^)]+)\)(?!.*weights_only)", re.MULTILINE),
            "new": r"\1checkpoint = torch.load(\2, weights_only=False)",
            "name": "checkpoint.py weights_only=False (broad)"
        },
        {
            "path": "MuseTalk/musetalk/utils/face_parsing/resnet.py",
            "old": re.compile(r"^(\s*)state_dict = torch\.load\(model_path\)", re.MULTILINE),
            "new": r"\1state_dict = torch.load(model_path, weights_only=False)",
            "name": "MuseTalk resnet.py legacy load"
        },
        {
            "path": "MuseTalk",
            "is_dir": True,
            "old": re.compile(r"torch\.load\(([^,)]+)\)(?!.*weights_only)"),
            "new": r"torch.load(\1, weights_only=False)",
            "name": "MuseTalk recursive torch.load protection"
        }
    ]
    
    for patch in patches:
        if patch.get("is_dir"):
            if not os.path.exists(patch["path"]): continue
            print(f"   📂 Patching directory: {patch['path']} ({patch['name']})")
            for root, _, files in os.walk(patch["path"]):
                for file in files:
                    if file.endswith(".py"):
                        fpath = os.path.join(root, file)
                        with open(fpath, "r") as f: content = f.read()
                        
                        modified = False
                        # Targeted regex: find torch.load calls without weights_only inside
                        new_content = re.sub(
                            r"torch\.load\(((?:(?!weights_only).)*?)\)",
                            r"torch.load(\1, weights_only=False)",
                            content,
                            flags=re.DOTALL
                        )
                        if new_content != content:
                            with open(fpath, "w") as f: f.write(new_content)
                            print(f"      ✅ Patched {file}")
            continue

        if not os.path.exists(patch["path"]):
            continue
        with open(patch["path"], "r") as f:
            content = f.read()
        
        unique_check = "except (ImportError, ValueError):" if "misc.py" in patch["path"] else ("force=True" if "builder.py" in patch["path"] else ("weights_only=False" if "checkpoint.py" in patch["path"] else "except TypeError:"))
        if unique_check in content:
            print(f"   ✅ {patch['name']} already patched")
            continue
            
        new_content, count = patch["old"].subn(patch["new"], content)
        if count > 0:
            with open(patch["path"], "w") as f:
                f.write(new_content)
            print(f"   ✅ {patch['name']} patch applied ({count} matches)")
            
            try:
                base_dir = os.path.dirname(patch["path"])
                subprocess.run(["find", base_dir, "-name", "*.pyc", "-delete"], check=False)
            except:
                pass
        else:
            print(f"   ⚠️ {patch['name']} pattern not found")

def _patch_mmengine():
    """
    Ensure all physical patches are applied and provides a runtime monkey-patch fallback.
    """
    _apply_physical_patches()
    
    print("🛠️ Verifying mmengine registry for Adafactor...")
    try:
        import mmengine.optim.optimizer.builder as builder
        import inspect
        source = inspect.getsource(builder.register_transformers_optimizers)
        if "force=True" in source or "except KeyError" in source:
            print("   ✅ mmengine Adafactor patch verified (source)")
            return

        import importlib, mmengine
        importlib.reload(mmengine)
        if hasattr(builder, 'register_transformers_optimizers'):
            orig_reg = builder.register_transformers_optimizers
            def safe_register():
                try: orig_reg()
                except KeyError: pass
            builder.register_transformers_optimizers = safe_register
            safe_register()
            print("   ✅ mmengine Adafactor monkey-patch applied")
    except Exception as e:
        print(f"   ⚠ Adafactor monkey-patch fallback: {e}")


